import json
import sys
import subprocess
import random
import string

def generate_random_hex():
    return ''.join(random.choices(string.hexdigits.lower(), k=16))

def evaluate_expression(expr):
    try:
        return str(eval(expr))
    except:
        return "0"

def substitute_template(template):
    return template.replace('{{', '').replace('}}', '').split('{{'))
    placeholders = [p for p in placeholders if p]
    return ''.join([template.replace(f'{{{p}}}', evaluate_expression(p)) for p in placeholders])

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        data = json.load(f)

    if 'template' not in data or 'command' not in data:
        sys.exit(1)

    template = data['template']
    command = data['command']

    # Generate random hex
    random_hex = generate_random_hex()

    # Substitute placeholders in template
    substituted_template = template
    placeholders = [p for p in re.findall(r'\{\{([^}]+)\}\}', template)]
    for expr in placeholders:
        substituted_template = substituted_template.replace(f'{{{expr}}}', str(evaluate_expression(expr)))

    # Prepare input for command
    input_lines = [random_hex, substituted_template]

    # Execute command with input
    process = subprocess.Popen(
        command.split(),
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True
    )
    stdout, stderr = process.communicate(input=input_lines)

    sys.exit(process.returncode)

import re

import json
import sys
import random
import re
import subprocess
import os

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        raise ValueError(f"Invalid expression: {expr}")

def substitute_template(template):
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))

    return re.sub(r'\{\{([^}]+)\}\}', replace_match, template)

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
        data = json.load(f)

    template = data['template']
    substituted_template = substitute_template(template)

    random_bytes = os.urandom(16)
    hex_value = random_bytes.hex().lower()

    command = data['command']

    input_lines = [hex_value, substituted_template]

    try:
        result = subprocess.run(
            command,
            shell=True,
            stdin=subprocess.PIPE,
            text=True,
            check=True,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            input='\n'.join(input_lines)
        )
        sys.stdout.write(result.stdout)
        sys.stderr.write(result.stderr)
    except subprocess.CalledProcessError as e:
        sys.exit(e.returncode)
    except Exception:
        sys.exit(1)

if __name__ == "__main__":
    main()
